package com.hmdp.ai.security;
import cn.dev33.satoken.SaManager;import cn.dev33.satoken.context.*;import cn.dev33.satoken.servlet.model.*;import com.hmdp.ai.api.mcp.McpController;import com.hmdp.ai.api.security.AiPermissionInterceptor;import com.hmdp.ai.application.mcp.McpApplicationService;import com.hmdp.ai.application.security.AiAuthorizationService;import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import org.springframework.web.method.HandlerMethod;import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.mock;
class AnonymousAiManagementAccessTest {@Test void anonymousMcpManagementRequestIsRejected()throws Exception{SaTokenContext previous=SaManager.getSaTokenContext();MockHttpServletRequest request=new MockHttpServletRequest("GET","/api/v1/mcp-servers");MockHttpServletResponse response=new MockHttpServletResponse();try{SaManager.setSaTokenContext(new SaTokenContextForThreadLocal());SaTokenContextForThreadLocalStorage.setBox(new SaRequestForServlet(request),new SaResponseForServlet(response),new SaStorageForServlet(request));McpController controller=new McpController(mock(McpApplicationService.class));HandlerMethod handler=new HandlerMethod(controller,McpController.class.getMethod("list"));boolean allowed=new AiPermissionInterceptor(mock(AiAuthorizationService.class)).preHandle(request,response,handler);assertThat(allowed).isFalse();assertThat(response.getStatus()).isEqualTo(401);assertThat(response.getContentAsString()).contains("AI_UNAUTHENTICATED");}finally{SaTokenContextForThreadLocalStorage.clearBox();SaManager.setSaTokenContext(previous);}}}
